pub static CLASS_CHUNKS: &[&[ClassDef]] = &[
    CLASSES_0,
    CLASSES_1,
    CLASSES_2,
    CLASSES_3,
    CLASSES_4,
    CLASSES_5,
];

pub fn class_def(name: &str) -> Option<&'static ClassDef> {
    CLASS_CHUNKS.iter().flat_map(|c| c.iter()).find(|c| c.name == name)
}

pub fn all_classes() -> impl Iterator<Item = &'static ClassDef> {
    CLASS_CHUNKS.iter().flat_map(|c| c.iter())
}
